#pragma once
#include "SensorUi.h"
#include "../ui/GeneralOptions.h"
#include <QPainter>
#include <QPainterPath>
#include <QJsonArray>
#include <QJsonDocument>
#include <QFileDialog>
#include <QSaveFile>
#include <QMessageBox>
namespace tunuino {
class SensitivityCurve final:public QWidget {
 class Plot final:public QWidget {
 public: SensitivityCurve *curve;explicit Plot(SensitivityCurve *c):QWidget(c),curve(c){setMinimumHeight(170);}
 void paintEvent(QPaintEvent*)override{QPainter p(this);p.fillRect(rect(),QColor("#242628"));auto data=curve->state();if(data.isEmpty()){p.setPen(Qt::white);p.drawText(rect(),Qt::AlignCenter,tr("Invalid curve points"));return;}auto xs=data["rpm"].toArray(),ys=data["volts"].toArray();QRectF area(52,12,width()-66,height()-49);p.setPen(QPen(QColor("#b1b1b1"),1,Qt::DashLine));for(int i=0;i<6;++i){double y=area.bottom()-area.height()*i/5;p.drawLine(QPointF(area.left(),y),QPointF(area.right(),y));p.drawText(QRectF(0,y-9,45,18),Qt::AlignRight,QString::number(i,'f',1));}QPainterPath path;QVector<QPointF> points;for(int i=0;i<xs.size();++i){double x=area.left()+(xs[i].toDouble()-xs[0].toDouble())/(xs.last().toDouble()-xs[0].toDouble())*area.width();p.drawLine(QPointF(x,area.top()),QPointF(x,area.bottom()));p.drawText(QRectF(x-24,area.bottom()+3,48,18),Qt::AlignCenter,QString::number(xs[i].toDouble(),'f',0));QPointF v(x,area.bottom()-ys[i].toDouble()/5*area.height());points<<v;if(i)path.lineTo(v);else path.moveTo(v);}auto fill=path;fill.lineTo(area.bottomRight());fill.lineTo(area.bottomLeft());fill.closeSubpath();const QColor colors[]={QColor("#f63b18"),QColor("#197bff"),QColor("#45bd26"),QColor("#e4a92a")};p.fillPath(fill,colors[qBound(0,option("curveColor",0),3)]);p.setPen(QPen(Qt::white,1));p.drawPath(path);for(auto v:points){p.setBrush(QColor("#bbbbbb"));p.drawEllipse(v,3,3);}p.drawText(QRectF(area.left(),height()-20,area.width(),18),Qt::AlignCenter,tr("RPM (rpm)"));p.save();p.translate(13,area.center().y());p.rotate(-90);p.drawText(QRectF(-60,-8,120,18),Qt::AlignCenter,tr("Sensitivity [V]"));p.restore();}
 };
public:
 explicit SensitivityCurve(QWidget *parent=nullptr):QWidget(parent){setObjectName("cam1Sensitivity");auto *layout=new QVBoxLayout(this);layout->setContentsMargins(4,4,4,4);auto *bar=SensorUi::toolbar(this);auto *open=bar->addAction(CalibrationAppearance::icon(CalibrationAppearance::Open),tr("Open curve"));auto *save=bar->addAction(CalibrationAppearance::icon(CalibrationAppearance::Save),tr("Save curve"));auto *reset=bar->addAction(CalibrationAppearance::icon(CalibrationAppearance::Defaults),tr("Restore reference"));bar->addSeparator();auto *help=bar->addAction(CalibrationAppearance::icon(CalibrationAppearance::Help),tr("Help"));layout->addWidget(bar);plot_=new Plot(this);layout->addWidget(plot_,1);table_=new QTableWidget(2,12,this);table_->setObjectName("sensitivityPoints");SensorUi::grid(table_);table_->verticalHeader()->show();table_->setVerticalHeaderLabels({"V","rpm"});table_->setEditTriggers(QAbstractItemView::DoubleClicked|QAbstractItemView::EditKeyPressed);table_->setMaximumHeight(78);for(int r=0;r<2;++r)for(int c=0;c<12;++c){auto *item=new QTableWidgetItem;item->setBackground(r?QColor("#666764"):QColor::fromHsvF(.28-c*.012,.7,.95));item->setForeground(r?QColor(Qt::white):QColor(Qt::black));table_->setItem(r,c,item);}layout->addWidget(table_);auto *notice=new QLabel(tr("Reference curve only. Proteus CAM 1 has fixed MAX9924 conditioning and no programmable voltage threshold. Edits are saved in the project; they cannot be written to this ECU."),this);notice->setWordWrap(true);layout->addWidget(notice);QString error;restore(defaultState(),true,error);connect(table_,&QTableWidget::itemChanged,this,[this]{plot_->update();});connect(reset,&QAction::triggered,this,[this]{QString e;restore(defaultState(),true,e);});connect(help,&QAction::triggered,this,[this,notice]{QMessageBox::information(this,tr("CAM 1 sensitivity"),notice->text());});connect(open,&QAction::triggered,this,[this]{file(false);});connect(save,&QAction::triggered,this,[this]{file(true);});}
 static QJsonObject defaultState(){return {{"rpm",QJsonArray{750,1318,1886,2455,3023,3591,4159,4727,5295,5864,6432,7000}},{"volts",QJsonArray{.20,.53,.84,1.18,1.51,1.57,1.63,1.69,1.75,1.82,1.88,1.94}}};}
 QJsonObject state()const{QJsonArray rpm,volts;for(int i=0;i<12;++i){bool x,y;const double a=table_->item(1,i)->text().toDouble(&x),b=table_->item(0,i)->text().toDouble(&y);if(!x||!y)return {};rpm<<a;volts<<b;}return {{"rpm",rpm},{"volts",volts}};}
 bool restore(const QJsonObject &value,bool apply,QString &error){const auto x=value["rpm"].toArray(),y=value["volts"].toArray();if(x.size()!=12||y.size()!=12){error=tr("Expected twelve sensitivity points.");return false;}for(int i=0;i<12;++i)if(!x[i].isDouble()||!y[i].isDouble()||!std::isfinite(x[i].toDouble())||!std::isfinite(y[i].toDouble())||std::abs(x[i].toDouble()-std::round(x[i].toDouble()))>1e-6||std::abs(y[i].toDouble()*100-std::round(y[i].toDouble()*100))>1e-6||x[i].toDouble()<0||x[i].toDouble()>20000||y[i].toDouble()<0||y[i].toDouble()>5||(i&&x[i].toDouble()<=x[i-1].toDouble())){error=tr("Use increasing RPM points in 0–20000 rpm and sensitivity values in 0–5 V.");return false;}if(apply){QSignalBlocker block(table_);for(int i=0;i<12;++i){table_->item(1,i)->setText(QString::number(x[i].toDouble(),'f',0));table_->item(0,i)->setText(QString::number(y[i].toDouble(),'f',2));}plot_->update();}return true;}
 QSize sizeHint()const override{const int sizes[]={520,720,940};return QSize(sizes[qBound(0,option("table2Size",1),2)],390);}
private:
 void file(bool write){const auto path=write?QFileDialog::getSaveFileName(this,tr("Save reference curve"),{},tr("Tunuino curve (*.tncurve)")):QFileDialog::getOpenFileName(this,tr("Open reference curve"),{},tr("Tunuino curve (*.tncurve)"));if(path.isEmpty())return;QString error;if(write){auto curve=state();if(!restore(curve,false,error)){QMessageBox::warning(this,tr("Curve"),error);return;}QSaveFile file(path);auto bytes=QJsonDocument(QJsonObject{{"format","tunuino-sensitivity-reference-v1"},{"curve",curve}}).toJson();if(!file.open(QIODevice::WriteOnly)||file.write(bytes)!=bytes.size()||!file.commit())QMessageBox::warning(this,tr("Curve"),tr("Could not save curve."));}else{QFile file(path);if(!file.open(QIODevice::ReadOnly)||file.size()>65536)return;auto doc=QJsonDocument::fromJson(file.readAll()).object();if(doc["format"]!="tunuino-sensitivity-reference-v1"||!restore(doc["curve"].toObject(),true,error))QMessageBox::warning(this,tr("Curve"),error);}}
 QTableWidget *table_;Plot *plot_;
};
}
